using System;using System.IO;using System.Linq;using System.Drawing;using System.Globalization;using System.Collections.Generic;using System.Windows.Forms;
namespace CircuitoStudio {
public sealed class ResidualSelectionForm:Form {
Project project;Circuit circuit;string file;List<ResidualRating> rows,visible;ComboBox kind,waveform,poles,supply;TextBox limit,rule,control,details;ListBox list;public bool Changed{get;private set;}
public ResidualSelectionForm(Project p,Circuit c,string library){project=p;circuit=c;file=library;rows=File.Exists(file)?ResidualSelection.Import(file):new List<ResidualRating>();Text="Diferenciais, relés e acessórios";Size=new Size(1220,820);MinimumSize=new Size(1120,720);Font=new Font("Segoe UI",10);StartPosition=FormStartPosition.CenterParent;var top=new FlowLayoutPanel{Dock=DockStyle.Top,Height=200,Padding=new Padding(8)};Add(top,"Importar CSV",Import);Add(top,"Modelo vazio",EmptyTemplate);Add(top,"Modelo com proteção atual",CurrentTemplate);Add(top,"Selecionar conjunto",Apply);Add(top,"Remover seleção",Remove);top.SetFlowBreak(top.Controls[top.Controls.Count-1],true);kind=Picker(top,"Conjunto",new[]{"RCCB integrado","Relé + sensor + atuador"},190);waveform=Picker(top,"Tipo exigido",new[]{"A definir","AC","A","F","B"},90);poles=Picker(top,"Polos",Enum.GetValues(typeof(PoleLayout)).Cast<PoleLayout>().Select(x=>BreakerSelection.PoleName(x)).ToArray(),85);top.SetFlowBreak(poles,true);limit=Field(top,"Sensibilidade máxima (mA)",90);rule=Field(top,"Referência da regra",540);top.SetFlowBreak(rule,true);control=Field(top,"Controle auxiliar (V)",90);supply=Picker(top,"Alimentação auxiliar",new[]{"Não se aplica / desconhecida","AC","DC"},220);Add(top,"Atualizar comparação",RefreshDetails);var note=new Label{Dock=DockStyle.Top,Height=65,Padding=new Padding(10),Text=c.Id+"; "+c.Voltage+" V; "+p.Frequency+" Hz. Tipo/limite de sensibilidade são requisitos declarados, sem regra normativa automática.\r\nRCCB/relé não substitui proteção de sobrecorrente. Relés/acessórios exigem conjunto documentado. Sem seletividade ou tempo de desligamento presumidos."};list=new ListBox{Dock=DockStyle.Top,Height=130,HorizontalScrollbar=true};details=new TextBox{Dock=DockStyle.Fill,Multiline=true,ReadOnly=true,ScrollBars=ScrollBars.Vertical,BackColor=Color.White};Controls.Add(details);Controls.Add(list);Controls.Add(note);Controls.Add(top);var selected=c.ResidualSelection;kind.SelectedIndex=selected==null?0:(int)selected.Rating.Kind;waveform.SelectedIndex=selected==null?0:(int)selected.RequiredWaveform;poles.SelectedIndex=selected==null?(c.Phases==PhaseMode.Trifasico?(int)PoleLayout.ThreePole:(int)PoleLayout.OnePoleNeutral):(int)selected.RequiredPoles;limit.Text=selected==null||selected.MaximumDeltaMilliA==0?"":selected.MaximumDeltaMilliA.ToString(CultureInfo.CurrentCulture);rule.Text=selected==null?"":selected.RequirementSource;control.Text=selected==null||selected.ControlVoltageV==0?"":selected.ControlVoltageV.ToString(CultureInfo.CurrentCulture);supply.SelectedIndex=selected==null?0:(int)selected.ControlSupply;kind.SelectedIndexChanged+=delegate{if(kind.SelectedIndex==0){control.Text="";supply.SelectedIndex=0;}RefreshRows();};waveform.SelectedIndexChanged+=delegate{RefreshDetails();};poles.SelectedIndexChanged+=delegate{RefreshDetails();};supply.SelectedIndexChanged+=delegate{RefreshDetails();};list.SelectedIndexChanged+=delegate{RefreshDetails();};Shown+=delegate{details.SelectionStart=0;details.SelectionLength=0;details.ScrollToCaret();list.Focus();};RefreshRows();}
static ComboBox Picker(FlowLayoutPanel panel,string label,string[] items,int width){panel.Controls.Add(new Label{Text=label,AutoSize=true,Margin=new Padding(5,8,3,0)});var box=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList,Width=width};box.Items.AddRange(items.Cast<object>().ToArray());panel.Controls.Add(box);return box;}
static TextBox Field(FlowLayoutPanel panel,string label,int width){panel.Controls.Add(new Label{Text=label,AutoSize=true,Margin=new Padding(5,8,3,0)});var field=new TextBox{Width=width,MaxLength=2000};panel.Controls.Add(field);return field;}
void Add(FlowLayoutPanel panel,string label,Action action){var button=new Button{Text=label,AutoSize=true};button.Click+=delegate{try{action();}catch(Exception ex){MessageBox.Show(this,ex.Message,"Diferenciais",MessageBoxButtons.OK,MessageBoxIcon.Warning);}};panel.Controls.Add(button);}
static double Number(string text){if(String.IsNullOrWhiteSpace(text))return 0;double value;if(text.Contains('.')&&text.Contains(',')||!Double.TryParse(text.Replace(',','.'),NumberStyles.Float,CultureInfo.InvariantCulture,out value)||Double.IsNaN(value)||Double.IsInfinity(value))throw new InvalidDataException("Informe números finitos e sem separador de milhares.");return value;}
ResidualBinding Candidate(ResidualRating r){return new ResidualBinding{Engine=ResidualSelection.EngineId,Rating=r,RequiredWaveform=(ResidualWaveform)waveform.SelectedIndex,RequiredPoles=(PoleLayout)poles.SelectedIndex,MaximumDeltaMilliA=Number(limit.Text),RequirementSource=rule.Text,ControlVoltageV=Number(control.Text),ControlSupply=(ControlSupply)supply.SelectedIndex};}
void RefreshRows(){visible=rows.Where(x=>x.Kind==(ResidualKind)kind.SelectedIndex).ToList();list.Items.Clear();foreach(var r in visible)list.Items.Add(r.Manufacturer+" / "+r.Reference+"; tipo "+r.Waveform+"; "+BreakerSelection.PoleName(r.Poles)+"; "+r.RatedA+" A; "+r.DeltaMilliA+" mA; sensor "+r.SensorReference+"; atuador "+r.ActuatorReference+"; acessório "+r.AccessoryReference);if(list.Items.Count>0)list.SelectedIndex=0;else RefreshDetails();}
void RefreshDetails(){var study=Engineering.Analyze(project);var saved=ResidualSelection.Evaluate(project,study,circuit,circuit.ResidualSelection);details.Text="SELEÇÃO SALVA\r\n"+saved.Status+"\r\n"+saved.Detail;if(list.SelectedIndex>=0){try{var candidate=ResidualSelection.Evaluate(project,study,circuit,Candidate(visible[list.SelectedIndex]));details.AppendText("\r\n\r\nCANDIDATO\r\n"+candidate.Status+"\r\n"+candidate.Detail);}catch(InvalidDataException ex){details.AppendText("\r\n\r\nREQUISITOS INCOMPLETOS/INVÁLIDOS: "+ex.Message);}}details.SelectionStart=0;details.SelectionLength=0;}
void Import(){using(var d=new OpenFileDialog{Filter="CSV|*.csv"})if(d.ShowDialog(this)==DialogResult.OK){var imported=ResidualSelection.Import(d.FileName);ResidualSelection.Export(imported,file);rows=imported;RefreshRows();}}
void EmptyTemplate(){SaveTemplate(false);}void CurrentTemplate(){SaveTemplate(true);}void SaveTemplate(bool current){using(var d=new SaveFileDialog{Filter="CSV|*.csv",FileName=current?"modelo-conjunto-protecao-atual.csv":"modelo-diferenciais.csv"})if(d.ShowDialog(this)==DialogResult.OK){if(String.Equals(Path.GetFullPath(d.FileName),Path.GetFullPath(file),StringComparison.OrdinalIgnoreCase))throw new InvalidDataException("Use outro nome para preservar a biblioteca.");ResidualSelection.Export(current?new[]{ResidualSelection.Template(project,circuit,(ResidualKind)kind.SelectedIndex)}:new ResidualRating[0],d.FileName);}}
void Apply(){if(list.SelectedIndex<0)return;ResidualSelection.Apply(project,circuit,Candidate(visible[list.SelectedIndex]));Changed=true;DialogResult=DialogResult.OK;Close();}
void Remove(){circuit.ResidualSelection=null;Changed=true;DialogResult=DialogResult.OK;Close();}
}
partial class Studio{void ConfigureResidualSelection(){if(circuit==null)throw new InvalidOperationException("Selecione um circuito.");using(var form=new ResidualSelectionForm(project,circuit,Path.Combine(userData,"diferenciais-conjuntos.csv")))if(form.ShowDialog(this)==DialogResult.OK&&form.Changed){Change();tabs.SelectedTab=studyPage;}}}
}
